#define STEPS 100
#define FAR   30.0
#define EPS   0.001
#define PI    3.14159265

float sphere(vec3 p, float r) {
    return length(p) - r;
}

float box(vec3 p, vec3 size) {
    vec3 q = abs(p) - size;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float blend(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

mat2 rotate(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

vec2 scene(vec3 p) {
    float ground = p.y;
    vec3 q = p - vec3(0.0, 1.0, 0.0);
    q.xz *= rotate(iTime * 0.5);
    float d1 = box(q, vec3(0.45)) - 0.08;
    float d2 = sphere(p - vec3(1.3 * sin(iTime), 1.0, 0.0), 0.45);
    float d = blend(d1, d2, 0.4);
    return ground < d ? vec2(ground, 0.0) : vec2(d, 1.0);
}

vec2 march(vec3 start, vec3 dir) {
    float t = 0.0;
    for (int i = 0; i < STEPS; i++) {
        vec2 h = scene(start + dir * t);
        if (h.x < EPS) return vec2(t, h.y);
        t += h.x;
        if (t > FAR) break;
    }
    return vec2(-1.0);
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(EPS, 0.0);
    return normalize(vec3(
        scene(p + e.xyy).x - scene(p - e.xyy).x,
        scene(p + e.yxy).x - scene(p - e.yxy).x,
        scene(p + e.yyx).x - scene(p - e.yyx).x));
}

float getShadow(vec3 start, vec3 dir) {
    float res = 1.0;
    float t = 0.02;
    for (int i = 0; i < 50; i++) {
        float h = scene(start + dir * t).x;
        res = min(res, 8.0 * h / t);
        t += clamp(h, 0.02, 0.2);
        if (res < 0.001 || t > 10.0) break;
    }
    return clamp(res, 0.0, 1.0);
}

vec4 tex(sampler2D s, vec3 p, vec3 n) {
    p -= vec3(0.0, 1.0, 0.0);
    p.xz *= rotate(iTime * 0.5);
    n.xz *= rotate(iTime * 0.5);
    vec3 w = n * n;
    return texture(s, fract(p.yz * 0.5)) * w.x
         + texture(s, fract(p.zx * 0.5)) * w.y
         + texture(s, fract(p.xy * 0.5)) * w.z;
}

vec3 bump(vec3 p, vec3 n) {
    vec2 e = vec2(0.01, 0.0);
    float h = tex(iChannel0, p, n).a;
    vec3 grad = vec3(tex(iChannel0, p + e.xyy, n).a,
                     tex(iChannel0, p + e.yxy, n).a,
                     tex(iChannel0, p + e.yyx, n).a) - h;
    grad /= e.x;
    grad -= n * dot(grad, n);
    return normalize(n - 0.08 * grad);
}

vec3 env(vec3 d) {
    if (d.y < 0.0) return vec3(0.1);
    return mix(vec3(1.2, 1.2, 1.1), vec3(0.2, 0.4, 0.8), sqrt(d.y));
}

vec3 pbr(vec3 n, vec3 v, vec3 l, vec3 base, float rough, float metal, float shadow) {
    vec3 h = normalize(v + l);
    float nl = max(dot(n, l), 0.0);
    float nv = max(dot(n, v), 0.001);
    float nh = max(dot(n, h), 0.0);
    float a2 = pow(rough, 4.0);
    float d = nh * nh * (a2 - 1.0) + 1.0;
    float D = a2 / (PI * d * d);
    float k = (rough + 1.0) * (rough + 1.0) / 8.0;
    float G = nl / (nl * (1.0 - k) + k) * nv / (nv * (1.0 - k) + k);
    vec3 F0 = mix(vec3(0.04), base, metal);
    vec3 F = F0 + (1.0 - F0) * pow(1.0 - max(dot(v, h), 0.0), 5.0);
    vec3 spec = D * G * F / (4.0 * nl * nv + 0.001);
    vec3 diff = (1.0 - F) * (1.0 - metal) * base / PI;
    vec3 direct = (diff + spec) * nl * shadow * PI;
    vec3 Fa = F0 + (1.0 - F0) * pow(1.0 - nv, 5.0) * (1.0 - rough);
    vec3 ambient = (1.0 - Fa) * (1.0 - metal) * base * 0.15
                 + Fa * env(reflect(-v, n)) * (1.0 - 0.7 * rough);
    return direct + ambient;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    float angle = 0.3 * iTime;
    vec3 cam = vec3(4.0 * sin(angle), 2.0, 4.0 * cos(angle));
    vec3 target = vec3(0.0, 0.8, 0.0);
    vec3 forward = normalize(target - cam);
    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up = cross(right, forward);
    vec3 dir = normalize(uv.x * right + uv.y * up + 1.8 * forward);
    vec3 sky = vec3(0.75, 0.85, 1.0);
    vec3 col = mix(sky, vec3(0.25, 0.45, 0.8), uv.y * 0.5 + 0.5);
    vec2 hit = march(cam, dir);
    if (hit.x > 0.0) {
        vec3 p = cam + dir * hit.x;
        vec3 n = getNormal(p);
        float checker = mod(floor(p.x) + floor(p.z), 2.0);
        vec3 base = mix(vec3(0.35), vec3(0.8), checker);
        float rough = 0.6;
        float metal = 0.0;
        if (hit.y > 0.5) {
            vec4 params = tex(iChannel1, p, n);
            base = tex(iChannel0, p, n).rgb;
            rough = params.x;
            metal = params.y;
            n = bump(p, n);
        }
        vec3 light = normalize(vec3(0.6, 0.8, 0.4));
        float shadow = getShadow(p + n * 0.01, light);
        col = pbr(n, -dir, light, base, rough, metal, shadow);
        col = mix(col, sky, 1.0 - exp(-0.004 * hit.x * hit.x));
    }
    col = pow(clamp(col, 0.0, 1.0), vec3(1.0 / 2.2));
    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec3 v = voronoi(uv, iTime);
    float h = smoothstep(0.0, 0.2, v.x);
    vec3 col = mix(vec3(0.05, 0.30, 0.08), vec3(0.45, 0.90, 0.25), v.y);
    col *= 0.75 + 0.25 * sin(2.0 * iTime + 6.2831 * v.z);
    col *= mix(0.15, 1.0, h);
    fragColor = vec4(col, h);
}

vec2 hash(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453);
}

vec2 point(vec2 cell, float size, float time) {
    return 0.5 + 0.4 * sin(time + 6.2831 * hash(mod(cell, size)));
}

vec3 voronoi(vec2 uv, float time) {
    float size = 8.0;
    vec2 p = uv * size;
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 best = vec2(8.0);
    vec2 id = vec2(0.0);
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 g = vec2(float(x), float(y));
            vec2 v = g + point(i + g, size, time) - f;
            if (dot(v, v) < dot(best, best)) {
                best = v;
                id = hash(mod(i + g, size));
            }
        }
    }
    float edge = 8.0;
    for (int y = -2; y <= 2; y++) {
        for (int x = -2; x <= 2; x++) {
            vec2 g = vec2(float(x), float(y));
            vec2 v = g + point(i + g, size, time) - f;
            if (dot(v - best, v - best) > 0.0001) {
                edge = min(edge, dot(0.5 * (best + v), normalize(v - best)));
            }
        }
    }
    return vec3(edge, id);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec3 v = voronoi(uv, iTime);
    float h = smoothstep(0.0, 0.2, v.x);
    float metal = smoothstep(0.55, 0.75, 0.5 + 0.5 * sin(0.7 * iTime + 6.2831 * v.z)) * h;
    float rough = mix(0.9, mix(0.6, 0.1, metal) + 0.15 * v.y, h);
    fragColor = vec4(rough, metal, 0.0, 1.0);
}
